function renmode(%mode){ $MODNAME = %mode; %mode = $MODNAME; if(%mode == "Elite"){ exec("Elite.cs"); for(%cl = Client::getFirst(); %cl != -1; %cl = Client::getNext(%cl)) echo("Changing Renegades Mods To... " @ $MODNAME @ " loading..."); remoteEval(%clientId, $MODNAME, $ItemFavoritesKey); bottomprintall("<jc><f0>Server is now running: <f2>" @ $MODNAME @ " <f0>enjoy the Quick Change!!\n<f0>Mission: <f2>" @ $missionName @ "   <f0>Mission Type: <f2>" @ $Game::missionType @ "\n<f0>Press <f1>'O'<f0> for specific objectives.", 15); } if(%mode == "reload"){ exec("reload.cs"); for(%cl = Client::getFirst(); %cl != -1; %cl = Client::getNext(%cl)) echo("Changing Renegades Mods To... " @ $MODNAME @ " loading..."); remoteEval(%clientId, $MODNAME, $ItemFavoritesKey); bottomprintall("<jc><f0>Server is now running: <f2>" @ $MODNAME @ " <f0>enjoy the Quick Change!!\n<f0>Mission: <f2>" @ $missionName @ "   <f0>Mission Type: <f2>" @ $Game::missionType @ "\n<f0>Press <f1>'O'<f0> for specific objectives.", 15); } if(%mode == "Elite2"){ exec("EliteRenegades.cs"); for(%cl = Client::getFirst(); %cl != -1; %cl = Client::getNext(%cl)) echo("Changing Renegades Mods To... " @ $MODNAME @ " loading..."); remoteEval(%clientId, $MODNAME, $ItemFavoritesKey); bottomprintall("<jc><f0>Server is now running: <f2>" @ $MODNAME @ " <f0>enjoy the Quick Change!!\n<f0>Mission: <f2>" @ $missionName @ "   <f0>Mission Type: <f2>" @ $Game::missionType @ "\n<f0>Press <f1>'O'<f0> for specific objectives.", 15); } if(%mode == "RenX"){ exec("RenX.cs"); for(%cl = Client::getFirst(); %cl != -1; %cl = Client::getNext(%cl)) echo("Changing Renegades Mods To... " @ $MODNAME @ " loading..."); remoteEval(%clientId, $MODNAME, $ItemFavoritesKey); bottomprintall("<jc><f0>Server is now running: <f2>" @ $MODNAME @ " <f0>enjoy the Quick Change!!\n<f0>Mission: <f2>" @ $missionName @ "   <f0>Mission Type: <f2>" @ $Game::missionType @ "\n<f0>Press <f1>'O'<f0> for specific objectives.", 15); } export("MODSWITCH::*", "config\\MODSWITCH.cs", False); }